22:
דע כי רב מה שיבא בהתחבר ובהמשך הדברים פתח ממה שהוא על משקל
אֶרֶץ או על משקל זולתו מן המשקלים והדמיונים, ישתנה בעמוד עליו ובהפרד אל
קמץ. ויש שיהיה הדבר האחד מזה בקצת המקומות נפרד בענין מחובר [נוסח דפוס=כמחובר]. הדמיון
בזה, כי אֶרֶץ משתנה ברוב מקומות האתנח וסוף פסוק אל הקמצות, ויש שיהיה
עוד בהם פתח. ויקרה כזה עוד בזולת שער אֶרֶץ ובפעלים החולפים ממה שיהיה
על משקל פָּעַל, ר"ל שיהיה בנפרד קמוץ כלו. ויש שישתנו [נוסח דפוס=שישתנה] דמיונים אחרים בעמוד
עליהם אל הצרי והסגול ואל זולתם עוד, כאשר תראה אותו בשער הזה. ואלה
המקומות נזכרים במסורת. ומשער אֶרֶץ מה שאינו משתנה כל עיקר, ר"ל מה שלא
יהיה לעולם באתנח וסוף פסוק כי אם פתח כאשר הוא בהמשך הדברים, כמו
נֶדֶר ותֶּבֶן וסֵפֶר ואֵפֶר ומֶלֶךְ ומֶלַח, יָצוּדוּ חֵרֶם (מיכה ז ב), ובֶּטַח, וּבֵין עֵֽדֶר (בראשית לב יז); ועוד הַמַּאֲכֶ֑לֶת (בראשית כב ו), כי אחריתו על דמיון אֶרֶץ. [הערה: וכן אָמְרָה קֹהֶ֑לֶת (קהלת ז כז), לָרֶ֑דֶת, וַתְּהִי לוֹ לְאֹמֶֽנֶת (רות ד טז), אף על פי שבאין באתנחתא וסוף-פסוק אינן יוצאין משיטתן ונקודתן בסגול. וכל לָלֶכֶת בר מן חד פסוק: שָׁם הֵם שָׁבִים לָלָכֶת (קהלת א ז). והמחבר קצר דבריו, וראה בטעמי המקרא.]  אלה כולם
וזולתם גם כן יבואו באתנח וסוף פסוק כאשר המה בזולת אתנח וסוף פסוק,
מהיות קצתם בצרי וקצתם בסגול. וכבר זכרו זה והדומה לו במסורת חכמי הסופרים,
ואין ענין לזכרו הנה, ודַיֵנו שהעירונו עליו לקחת אותו ממקומו. אבל מה שהצורך
מביא [נוסח דפוס=אביא] אל זכרו הנה ממה שהוא בהפרד בחלוף מה שהוא בהתחבר, הוא כמו
השתנות רוב הפעלים החולפים והעתידים בהפרד ממה [נוסח דפוס=מה] שהם בהתחבר. וזה כאמרו
בהתחבר וּבֵרַכְךָ֔ בָּאָרֶץ (דברים כח ח), וְהֵיטִבְךָ וְהִרְבְּךָ֖ (דברים ל ה), בשבא תחת הכ"ף
ותחת הבי"ת, ונאמר בהפרד וְשָׁכַב בְּשַׂלְמָתוֹ וּבֵרְכֶ֑ךָּ (דברים כד יג), וּבֵרַכְךָ וְהִרְבֶּ֑ךָ
(דברים ז יג) – בסגול; ונאמר בהפרד אָבִיךָ קָּנֶ֔ךָ (דברים לב ו), וההקשה שיהיה בהתחבר
קָנְךָ בשבא, על משקל אֲשֶׁר קָרְךָ֜ (דברים כה יח), הוּא עָשְׂךָ֖ וַיְכֹנְנֶךָ (דברים לב ו), כי
הוא פועל חולף כמוהם, אפס כי הם שמשו בו בהפרד בסגול; כמו שנאמר
בהתחבר צוּר יְלָדְךָ֖ תֶּשִׁי (דברים לב יח), ובהפרד שְׁמַע לְאָבִיךָ זֶה יְלָדֶ֑ךָ (משלי כג כב);
ונאמר בהפרד וְשָׁב… אֶת שְׁבוּתְךָ וְרִחֲמֶךָ (דברים ל ג), על משקל וְשָׁכַב בְּשַׂלְמָתוֹ וּבֵרֲכֶךָּ,
והמשפט בהתחבר שיהיה בשבא, על משקל וּבֵרַכְךָ בָּאָרֶץ; ונאמר [נוסח דפוס=ויאמר] בהפרד כַּאֲשֶׁר
הִשְׁבִּיעֶךָ (בראשית נ ו), והמשפט בהתחבר להיות בשבא ופתח; ונאמר כִּי לֹא אֹתְךָ
מָאָ֔סוּ כִּי אֹתִי מָאֲס֖וּ (ש"א ח ז), בקמץ בהפרד והוא זקף, כי הנפרד הרבה פעמים
שיהיה בזקף; ונאמר בהתחבר כִּי גָבְר֤וּ עָלֵינוּ (ש"ב יא כג), ובהפרד: מֵאֲרָיוֹת גָּבֵֽרוּ (ש"ב א כג);
ועוד וְשָׁמְר֥וּ… אֶת הַשַּׁבָּת (שמות לא טז) – אֹכֶל בֶּעָרִים וְשָׁמָֽרוּ (בראשית מא לה);
אֲשֶׁר בָּזְז֖וּ (במדבר לא לב) – וְאֶת כָּל חֵילָם בָּזָֽזוּ (במדבר לא ט);
וְטָהֲרָ֖ה מִמְּקֹר דָּמֶיהָ (ויקרא יב ז) – וְכִפֶּר… וְטָהֵֽרָה (ויקרא יב ח);
לָקְט֥וּ לֶחֶם מִשְׁנֶה (שמות טז כב) – לְפִי אָכְלוֹ לָקָֽטוּ (שמות טז יח);
וַיְחִ֤י יַעֲקֹב (בראשית מז כח) – כַּאֲשֶׁר שָׁמַעְתָּ אַתָּה וַיֶּחִי (דברים ד לג);
וַיִּתְאַבְּל֥וּ הָעָם (במדבר יד לט) – וַיִּתְאַבָּ֑לוּ (שמות לג ד);
בָּאוּ מְלָכִים נִלְחָ֔מוּ אָז נִלְחֲמוּ֙ מַלְכֵי כְנַעַן (שופטים ה יט);
מַה יִּקָּחֲךָ֥ לִבֶּךָ (איוב טו יב) – וּמִשָּׁם יִקָּחֶֽךָ (דברים ל ד);
תְּרוּעָה יִתְקְע֖וּ (במדבר י ו) – וְאִם בְּאַחַת יִתְקָ֑עוּ (שם פסוק ד);
אֲשֶׁר תִּקְח֖וּ (שמות כה ג) –

מִמַּחֲצִיתָם תִּקָּ֑חוּ (במדבר לא כט);
בָּאֵשׁ יִשְׂרְפ֤וּ (ויקרא כ יד) – בָּאֵשׁ תִּשְׂרֹֽפוּ (שמות יב י);
תִּשְׁמְר֕וּ לְהַקְרִיב לִי (במדבר כח ב) – אַךְ אֶת שַׁבְּתֹתַי תִּשְׁמֹ֑רוּ (שמות לא יג);
יִרְחֲצוּ־מַיִם (שמות ל כ) – וּבְקָרְבָתָם אֶל הַמִּזְבֵּחַ יִרְחָ֑צוּ (שמות מ לב);
זֹאת הַחַיָּה אֲשֶׁר תֹּאכְל֔וּ (ויקרא יא ב) – אֹתָם תֹּאכֵֽלוּ (ויקרא יא ט);
וַאֲדַבְּרָ֣ה בְאָזְנֵיהֶם (דברים לא כח) – וַאֲדַבֵּ֑רָה (דברים לב א);
וְאֶת אֵלֶּה תְּשַׁקְּצ֣וּ (ויקרא יא יג) – וְאֶת נִבְלָתָם תְּשַׁקֵּֽצוּ (ויקרא יא יא).
